"""Command line interface for interacting with the phe library.

Provides the `pheutil` command with subcommands to generate keys,
encrypt, decrypt and perform homomorphic operations on encrypted
numbers serialised as JSON.
"""

import json

import click

from phe import paillier
from phe.util import int_to_base64, base64_to_int


@click.group("pheutil")
def cli():
    """CLI for interacting with the phe library.

    This command line tool can be used to generate paillier private
    keys, extract public keys, encrypt and decrypt numbers, and
    compute simple homomorphic operations over encrypted numbers.
    """


def _parse_plaintext(plaintext):
    """Parse a string into an int or float."""
    try:
        return int(plaintext)
    except ValueError:
        return float(plaintext)


def _load_public_key(file):
    """Deserialise a PaillierPublicKey from a JWK JSON file."""
    public_jwk = json.load(file)
    return paillier.PaillierPublicKey(n=base64_to_int(public_jwk['n']))


def _load_private_key(file):
    """Deserialise a PaillierPrivateKey from a JWK JSON file."""
    private_jwk = json.load(file)
    public_key = paillier.PaillierPublicKey(
        n=base64_to_int(private_jwk['pub']['n']))
    return paillier.PaillierPrivateKey(
        public_key,
        p=base64_to_int(private_jwk['p']),
        q=base64_to_int(private_jwk['q']))


def _load_encrypted_numbers(public_key, file):
    """Deserialise a JSON list of encrypted numbers."""
    return [
        paillier.EncryptedNumber(
            public_key,
            base64_to_int(serialised['v']),
            int(serialised['e']))
        for serialised in json.load(file)
    ]


def _dump_encrypted_numbers(encrypted_numbers, output):
    """Serialise a list of encrypted numbers to JSON."""
    json.dump([
        {
            'v': int_to_base64(encrypted_number.ciphertext()),
            'e': encrypted_number.exponent
        }
        for encrypted_number in encrypted_numbers
    ], output)


@cli.command()
@click.argument("output", type=click.File('w'), default="-")
@click.option("--keysize", type=int, default=2048,
              help="The key size in bits.")
@click.option("--id", type=str, default=None,
              help="Add an identifying comment to the key.")
def genpkey(keysize, id, output):
    """Generate a paillier private key.

    OUTPUT the name of a file to write the generated private key to.
    If OUTPUT is '-' the key will be written to stdout.
    """
    public_key, private_key = paillier.generate_paillier_keypair(
        n_length=keysize)

    jwk_public_key = {
        'kty': 'DAJ',
        'alg': 'PAI-GN1',
        'n': int_to_base64(public_key.n)
    }
    if id:
        jwk_public_key['kid'] = id

    jwk_private_key = {
        'kty': 'DAJ',
        'kid': id,
        'pub': jwk_public_key,
        'p': int_to_base64(private_key.p),
        'q': int_to_base64(private_key.q)
    }

    json.dump(jwk_private_key, output)


@cli.command()
@click.argument("private", type=click.File('r'))
@click.argument("output", type=click.File('w'), default="-")
def extract(private, output):
    """Extract the public key from a private key.

    PRIVATE a file containing the private key - generated with
    the genpkey command.

    OUTPUT the name of a file to write the public key to. If OUTPUT
    is '-' the key will be written to stdout.
    """
    private_jwk = json.load(private)
    json.dump(private_jwk['pub'], output)


@cli.command()
@click.argument("public", type=click.File('r'))
@click.argument("plaintext", type=str)
@click.option("--output", type=click.File('w'), default="-",
              help="Defaults to stdout.")
def encrypt(public, plaintext, output):
    """Encrypt a number with the given public key.

    PUBLIC the file containing the json serialised public key.

    PLAINTEXT the number to encrypt. This number can be an int or a
    float. Floats are not perfectly represented so take care.
    Supports scientific notation e.g. 1e-20 or -10550e20.

    Encrypting a small number is fast, encrypting larger numbers
    will take longer.
    """
    public_key = _load_public_key(public)

    encrypted_number = public_key.encrypt(_parse_plaintext(plaintext))
    _dump_encrypted_numbers([encrypted_number], output)


@cli.command()
@click.argument("private", type=click.File('r'))
@click.argument("ciphertext", type=click.File('r'), nargs=-1)
@click.option("--output", type=click.File('w'), default="-",
              help="Defaults to stdout.")
def decrypt(private, ciphertext, output):
    """Decrypt ciphertext(s) with the given private key.

    PRIVATE the file containing the json serialised private key.

    CIPHERTEXT file(s) containing json serialised encrypted numbers.
    Each decrypted number will be written on its own line.
    """
    private_key = _load_private_key(private)

    for file in ciphertext:
        for encrypted_number in _load_encrypted_numbers(
                private_key.public_key, file):
            output.write(str(private_key.decrypt(encrypted_number)))
            output.write('\n')


@cli.command()
@click.argument("public", type=click.File('r'))
@click.argument("encrypted_a", type=click.File('r'))
@click.argument("encrypted_b", type=click.File('r'))
@click.option("--output", type=click.File('w'), default="-",
              help="Defaults to stdout.")
def addenc(public, encrypted_a, encrypted_b, output):
    """Add two encrypted numbers together.

    PUBLIC the file containing the json serialised public key.

    ENCRYPTED_A a file containing json serialised encrypted numbers.

    ENCRYPTED_B a file containing json serialised encrypted numbers.

    Both files must contain the same number of encrypted values; the
    output contains the element-wise sums.
    """
    public_key = _load_public_key(public)

    encodings_a = _load_encrypted_numbers(public_key, encrypted_a)
    encodings_b = _load_encrypted_numbers(public_key, encrypted_b)

    if len(encodings_a) != len(encodings_b):
        raise click.ClickException(
            "Both files must contain the same number of encrypted "
            "values")

    _dump_encrypted_numbers(
        [enc_a + enc_b for enc_a, enc_b in zip(encodings_a, encodings_b)],
        output)


@cli.command()
@click.argument("public", type=click.File('r'))
@click.argument("encrypted", type=click.File('r'))
@click.argument("plaintext", type=str)
@click.option("--output", type=click.File('w'), default="-",
              help="Defaults to stdout.")
def add(public, encrypted, plaintext, output):
    """Add a plaintext number to an encrypted number.

    PUBLIC the file containing the json serialised public key.

    ENCRYPTED a file containing json serialised encrypted numbers.

    PLAINTEXT the number to add.
    """
    public_key = _load_public_key(public)

    value = _parse_plaintext(plaintext)
    encodings = _load_encrypted_numbers(public_key, encrypted)

    _dump_encrypted_numbers(
        [enc + value for enc in encodings], output)


@cli.command()
@click.argument("public", type=click.File('r'))
@click.argument("encrypted", type=click.File('r'))
@click.argument("plaintext", type=str)
@click.option("--output", type=click.File('w'), default="-",
              help="Defaults to stdout.")
def multiply(public, encrypted, plaintext, output):
    """Multiply an encrypted number with a plain number.

    PUBLIC the file containing the json serialised public key.

    ENCRYPTED a file containing json serialised encrypted numbers.

    PLAINTEXT the number to multiply by.
    """
    public_key = _load_public_key(public)

    value = _parse_plaintext(plaintext)
    encodings = _load_encrypted_numbers(public_key, encrypted)

    _dump_encrypted_numbers(
        [enc * value for enc in encodings], output)


if __name__ == '__main__':
    cli()

